const input = items[0].json;

const payload = input.body ?? input;
const data = payload.data ?? payload;

// ================================
// CONFIGURACIÓN DEL LEAD_ID
// ================================
// Si quieres empezar en L-0001, deja 1.
// Si ya tienes leads reales y quieres empezar en L-0008, pon 8.
// IMPORTANTE: esto solo se usa la primera vez que se inicializa el contador.
const START_FROM = 1;

// Nombre interno del contador para no mezclarse con otros workflows
const STATIC_KEY = 'NC_DIAGNOSTICO_LEADS';

// ================================
// FUNCIONES AUXILIARES
// ================================

function normalize(text) {
  return String(text || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function extractFields(input, payload, data) {
  if (Array.isArray(data.fields)) return data.fields;
  if (Array.isArray(payload.fields)) return payload.fields;
  if (Array.isArray(input.fields)) return input.fields;

  const containers = [data, payload, input];

  for (const container of containers) {
    if (!container || typeof container !== 'object') continue;

    const found = Object.values(container).filter(v =>
      v &&
      typeof v === 'object' &&
      (v.label || v.title || v.key || v.name) &&
      Object.prototype.hasOwnProperty.call(v, 'value')
    );

    if (found.length > 0) return found;
  }

  return [];
}

function collectOptions(obj, depth = 0, acc = []) {
  if (!obj || typeof obj !== 'object' || depth > 6) return acc;

  if (Array.isArray(obj)) {
    for (const item of obj) {
      if (item && typeof item === 'object') {
        const id = item.id ?? item.key ?? item.value;
        const text = item.text ?? item.label ?? item.title ?? item.name;

        if (id !== undefined && text !== undefined) {
          acc.push({ id: String(id), text: String(text) });
        }
      }

      collectOptions(item, depth + 1, acc);
    }

    return acc;
  }

  for (const key of Object.keys(obj)) {
    collectOptions(obj[key], depth + 1, acc);
  }

  return acc;
}

function resolveFieldValue(field) {
  let value = field.value;

  const options = collectOptions(field);
  const optionMap = {};

  for (const option of options) {
    optionMap[String(option.id)] = String(option.text);
  }

  function resolveOne(v) {
    if (v === null || v === undefined) return '';

    if (typeof v === 'object') {
      const directText = v.text ?? v.label ?? v.title ?? v.name;
      if (directText !== undefined) return String(directText);

      const id = v.id ?? v.key ?? v.value;
      if (id !== undefined && optionMap[String(id)]) {
        return optionMap[String(id)];
      }

      return JSON.stringify(v);
    }

    const raw = String(v);
    return optionMap[raw] ?? raw;
  }

  if (Array.isArray(value)) {
    return value.map(resolveOne).join(', ');
  }

  return resolveOne(value);
}

// ================================
// EXTRAER CAMPOS DE TALLY
// ================================

const fields = extractFields(input, payload, data);

const byLabel = {};
const byNorm = {};

for (const field of fields) {
  const label = (field.label || field.title || field.key || field.name || '').trim();
  const value = resolveFieldValue(field);

  byLabel[label] = value;
  byNorm[normalize(label)] = value;
}

function pick(...possibleLabels) {
  for (const label of possibleLabels) {
    const value = byNorm[normalize(label)];

    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return value;
    }
  }

  return '';
}

// ================================
// RESPONSE ID DE TALLY
// ================================

const responseId =
  data.responseId ||
  data.respondentId ||
  data.submissionId ||
  payload.responseId ||
  payload.respondentId ||
  payload.submissionId ||
  input.responseId ||
  input.respondentId ||
  input.submissionId ||
  data.id ||
  '';

// ================================
// GENERAR LEAD_ID ÚNICO
// ================================

// En tu n8n solo funcionan 'global' y 'node'.
// Usamos 'global' para que sea más estable.
const staticData = $getWorkflowStaticData('global');

if (!staticData[STATIC_KEY] || typeof staticData[STATIC_KEY] !== 'object') {
  staticData[STATIC_KEY] = {
    nextLeadNumber: START_FROM,
    leadIdByResponseId: {}
  };
}

const store = staticData[STATIC_KEY];

if (!store.leadIdByResponseId || typeof store.leadIdByResponseId !== 'object') {
  store.leadIdByResponseId = {};
}

if (
  store.nextLeadNumber === undefined ||
  store.nextLeadNumber === null ||
  Number.isNaN(Number(store.nextLeadNumber))
) {
  store.nextLeadNumber = START_FROM;
}

function makeLeadId(number) {
  return `L-${String(number).padStart(4, '0')}`;
}

let leadId;

if (responseId && store.leadIdByResponseId[responseId]) {
  leadId = store.leadIdByResponseId[responseId];
} else {
  leadId = makeLeadId(Number(store.nextLeadNumber));

  if (responseId) {
    store.leadIdByResponseId[responseId] = leadId;
  }

  store.nextLeadNumber = Number(store.nextLeadNumber) + 1;
}

// ================================
// DEBUG TEMPORAL
// ================================

const debugCampos = Object.entries(byLabel)
  .map(([key, value]) => `${key}: ${value}`)
  .join(' || ');

// ================================
// SALIDA FINAL PARA GOOGLE SHEETS
// ================================

return [
  {
    json: {
      Lead_ID: leadId,

      Fecha:
        data.createdAt ||
        payload.createdAt ||
        input.createdAt ||
        new Date().toISOString(),

      Nombre_y_apellidos: pick(
        'Nombre',
        'Nombre y apellidos',
        'Nombre_y_apellidos',
        'Nombre completo'
      ),

      Email: pick(
        'Email',
        'Correo electrónico',
        'Correo electronico'
      ),

      WhatsApp: pick(
        'WhatsApp',
        'Whatsapp',
        'Teléfono',
        'Telefono',
        'Móvil',
        'Movil'
      ),

      Idioma: pick(
        'Idioma preferido',
        'Idioma'
      ),

      En_Espana: pick(
        '¿Estás ya en España?',
        'Estás ya en España',
        'Estas ya en España',
        'Estas ya en Espana',
        '¿Estas ya en Espana?',
        'En_Espana',
        'En España',
        'En Espana'
      ),

      Situacion_actual: pick(
        'Situación actual',
        'Situacion actual',
        'Situacion_actual',
        '¿Cuál es tu situación actual?',
        'Cual es tu situacion actual'
      ),

      Origen_ingresos: pick(
        'Origen de ingresos',
        'Origen ingresos',
        'Origen_ingresos',
        'Origen de tus ingresos',
        '¿De dónde vienen tus ingresos?',
        'De donde vienen tus ingresos',
        'Fuente de ingresos',
        'Ingresos'
      ),

      Duda_principal: pick(
        'Tu duda principal hoy',
        'Duda principal',
        'Duda_principal'
      ),

      Resumen_caso: pick(
        'Explícame tu situación en 5–7 líneas',
        'Explicame tu situacion en 5-7 lineas',
        'Explícame tu situación',
        'Explicame tu situacion',
        'Explícame tu caso en 5–7 líneas',
        'Explicame tu caso en 5-7 lineas',
        'Explícame tu caso',
        'Explicame tu caso',
        'Cuéntame tu caso',
        'Cuentame tu caso',
        'Describe tu situación',
        'Describe tu situacion',
        'Resumen caso',
        'Resumen_caso'
      ),

      Urgencia: pick(
        'Urgencia'
      ),

      Consentimiento: pick(
        'Consentimiento'
      ),

      Debug_campos: debugCampos
    }
  }
];

